void RemoteAccess::registerRoutes(httplib::Server& svr, std::shared_ptr<AuthenticationManager> auth)
{
    svr.Get("/computer/api/json", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleComputerapijsonGetRequest(req, res, auth);
    });
    svr.Get("/api/json", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleApijsonGetRequest(req, res, auth);
    });
    svr.Get("/job/{name}/api/json", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleJobnameapijsonGetRequest(req, res, auth);
    });
    svr.Get("/job/{name}/config.xml", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleJobnameconfigxmlGetRequest(req, res, auth);
    });
    svr.Get("/job/{name}/lastBuild/api/json", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleJobnamelastBuildapijsonGetRequest(req, res, auth);
    });
    svr.Get("/job/{name}/{number}/logText/progressiveText", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleJobnamenumberlogTextprogressiveTextGetRequest(req, res, auth);
    });
    svr.Get("/queue/api/json", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleQueueapijsonGetRequest(req, res, auth);
    });
    svr.Get("/queue/item/{number}/api/json", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleQueueitemnumberapijsonGetRequest(req, res, auth);
    });
    svr.Get("/view/{name}/api/json", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleViewnameapijsonGetRequest(req, res, auth);
    });
    svr.Get("/view/{name}/config.xml", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleViewnameconfigxmlGetRequest(req, res, auth);
    });
    svr.Head("/api/json", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleApijsonHeadRequest(req, res, auth);
    });
    svr.Post("/createItem", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCreateItemPostRequest(req, res, auth);
    });
    svr.Post("/createView", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCreateViewPostRequest(req, res, auth);
    });
    svr.Post("/job/{name}/build", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleJobnamebuildPostRequest(req, res, auth);
    });
    svr.Post("/job/{name}/config.xml", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleJobnameconfigxmlPostRequest(req, res, auth);
    });
    svr.Post("/job/{name}/doDelete", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleJobnamedoDeletePostRequest(req, res, auth);
    });
    svr.Post("/job/{name}/disable", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleJobnamedisablePostRequest(req, res, auth);
    });
    svr.Post("/job/{name}/enable", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleJobnameenablePostRequest(req, res, auth);
    });
    svr.Post("/job/{name}/lastBuild/stop", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleJobnamelastBuildstopPostRequest(req, res, auth);
    });
    svr.Post("/view/{name}/config.xml", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleViewnameconfigxmlPostRequest(req, res, auth);
    });
}

